        for customer in self._orders.list_customers():
            _, value = self._lifetime(self._orders.list_for_customer(customer.customer_id))
            if value > 0:
                ranked.append({"customer_id": customer.customer_id, "name": customer.name,
                               "lifetime_value_cents": value})
        ranked.sort(key=lambda c: (-c["lifetime_value_cents"], c["customer_id"]))
        return Response(200, {"customers": ranked[:limit]})

    def _lifetime(self, orders: list[Order]) -> tuple[int, int]:
        active = [o for o in orders if o.status != "cancelled"]
        return len(active), sum(self._orders.summarize(o).total_cents for o in active)
